--- a/is-domain-valid.js
+++ b/is-domain-valid.js
@@ -0,0 +1,117 @@
+let tldList = require("./tld-list");
+let isDomainValid = (e, t) => {
+  if (typeof e != "string") {
+    return {
+      result: false,
+      message: "Invalid type. Pass domain as a string"
+    };
+  }
+  e = e.toLowerCase().trim();
+  t = {
+    checkTld: true,
+    allowIdn: true,
+    allowSubdomain: true,
+    allowWildcard: false,
+    ...t
+  };
+  if (!e || e.length < 1) {
+    return {
+      result: false,
+      message: "No domain provided"
+    };
+  }
+  if (e.length > 253) {
+    return {
+      result: false,
+      message: "Domain contains more than 253 characters"
+    };
+  }
+  var s;
+  var e = e.split(".");
+  if (!e || e.length < 2) {
+    return {
+      result: false,
+      message: "Domain has to contain at least two labels"
+    };
+  }
+  if (e.length > 2) {
+    if (!t.allowSubdomain) {
+      return {
+        result: false,
+        message: "Subdomain is not allowed without allowSubdomain option"
+      };
+    }
+    if (e[0] === "*") {
+      if (!t.allowWildcard) {
+        return {
+          result: false,
+          message: "Wildcard is not allowed without allowWildcard option"
+        };
+      }
+      e.shift();
+    }
+  }
+  for (s of e) {
+    if (s.length > 63) {
+      return {
+        result: false,
+        message: `Label ${s} contains more than 63 characters`
+      };
+    }
+    if (s.match(/[^a-zA-Z0-9\-]/)) {
+      return {
+        result: false,
+        message: `Label ${s} contains a invalid character(s)`
+      };
+    }
+    if (s.substr(0, 1) === "-") {
+      return {
+        result: false,
+        message: `Label ${s} begins with hyphen`
+      };
+    }
+    if (s.substr(-1) === "-") {
+      return {
+        result: false,
+        message: `Label ${s} ends with hyphen`
+      };
+    }
+    let e = s;
+    if (t.allowIdn) {
+      var n = (s.match(/xn--/g) || []).length;
+      if (n === 1) {
+        if (s.indexOf("xn--") !== 0) {
+          return {
+            result: false,
+            message: `Label ${s} contains xn-- pointer not at the very beginning`
+          };
+        }
+        e = s.substr("xn--".length);
+      } else if (n > 1) {
+        return {
+          result: false,
+          message: `Label ${s} contains more than one xn-- pointers`
+        };
+      }
+    }
+    if (e.indexOf("--") !== -1) {
+      return {
+        result: false,
+        message: `Label ${s} contains consecutive hyphens`
+      };
+    }
+  }
+  if (t.checkTld) {
+    e = e[e.length - 1];
+    if (tldList.indexOf(e) === -1) {
+      return {
+        result: false,
+        message: `Tld ${e} is not allowed`
+      };
+    }
+  }
+  return {
+    result: true
+  };
+};
+module.exports = isDomainValid;
